"""Crop checked source windows; final video is generated by MediaMixVertical."""
import json,hashlib,subprocess
from pathlib import Path
r=Path('content/episode-009');out=r/'media/prepared';out.mkdir(parents=True,exist_ok=True)
source=r/'media/assets/fastlane-interview.mp4';parent=hashlib.sha256(source.read_bytes()).hexdigest()
timeline=json.loads((r/'production/timeline.json').read_text());d={s['id']:s['durationFrames']/30 for s in timeline['scenes']}
# Source windows retain actual speed; Schedule uses a labeled pause on its exact 814s frame for readability. The account→schedule edit omits intervening steps.
parts={
'seg-001':[(797.5,d['seg-001'],[630,150,520,690])],
'seg-003':[(820,d['seg-003'],[630,130,520,875])],
'seg-004':[(805.5,1.8,[330,135,1050,765]),(814.0,d['seg-004']-1.8,[340,250,1035,350])],
'seg-005':[(170.5,d['seg-005'],[500,60,1000,1000])],
'seg-008':[(699,d['seg-008'],[500,60,1000,1000])],
'seg-010':[(797.5,2.4,[630,130,520,875]),(805.5,2.5,[330,135,1050,765]),(814.0,d['seg-010']-4.9,[340,250,1035,350])],
}
records=[]
def run(args):subprocess.run(['ffmpeg','-hide_banner','-loglevel','error','-y',*args],check=True)
for seg,items in parts.items():
 files=[]
 for i,(start,seconds,crop) in enumerate(items):
  x,y,w,h=crop;p=out/f'{seg}-{i}.mp4';freeze=seg in ['seg-004','seg-010'] and i==len(items)-1;rate=1.0;vf=f'crop={w}:{h}:{x}:{y},scale=984:760:force_original_aspect_ratio=decrease,pad=984:760:(ow-iw)/2:(oh-ih)/2:color=black,setsar=1,setpts=PTS-STARTPTS'+(f',tpad=stop_mode=clone:stop_duration={seconds}' if freeze else '')
  run(['-ss',str(start),'-t',str(.04 if freeze else seconds),'-i',str(source),'-t',str(seconds),'-vf',vf,'-an','-r','30','-c:v','libx264','-preset','fast','-crf','18','-pix_fmt','yuv420p',str(p)])
  files.append(p);records.append(dict(segmentId=seg,part=i,sourcePath=str(source),sourceSha256=parent,sourceStartSeconds=start,seconds=seconds,playbackRate=1,freezeForReadability=freeze,cropPixels=crop,outputPath=str(p)))
 listing=out/f'{seg}.concat.txt';listing.write_text(''.join("file '"+p.name+"'\n" for p in files))
 run(['-f','concat','-safe','0','-i',str(listing),'-c','copy','-movflags','+faststart',str(out/f'{seg}.mp4')]);print(seg,d[seg],flush=True)
(r/'production/edit-recipe.json').write_text(json.dumps(dict(durationBasis='measured-TTS-timeline',sourceSha256=parent,parts=records),ensure_ascii=False,indent=2)+'\n')
observations={
'seg-001':('Cal AI的候选宣传内容，手机应用与食物图集可见；裁掉热门参考视频浏览量。',['候选','Cal AI','宣传']),
'seg-003':('同一历史界面的卡片选择和切换，X、Edit、勾选控件可见；未演示网站输入。',['卡片','跳过','留下']),
'seg-004':('真实Select Platforms账号选择后，剪到Schedule中Post ASAP与Schedule for Later；中间步骤省略，不证明上线。',['账号','排期','Schedule']),
'seg-005':('创始人Gaurav本人采访画面，为本人营销困难自述配图；不是用户实测。',['创始人','营销','需求']),
'seg-008':('Gaurav本人谈话，为观察共享屏幕及界面迭代自述配图；没有真实客户通话录像。',['访谈','共享屏幕','界面']),
'seg-010':('回到观众已见的Cal AI候选，再到现在/稍后排期选项，回收已展示的产品用途。',['候选','排期','内容']),
}
entries=[]
for seg,(summary,keywords) in observations.items():
 sha=hashlib.sha256((out/f'{seg}.mp4').read_bytes()).hexdigest();entries.append(dict(segmentId=seg,mediaId=f'episode-009:media:{seg}-{sha[:12]}',sha256=sha,textSummary=summary,keywords=keywords,inspection='Codex checked original source frames; prepared output still requires bounded clip inspection.'))
(r/'media/observations.json').write_text(json.dumps(entries,ensure_ascii=False,indent=2)+'\n')
